// GroupsServiceHandler is an implementation of the groups.v1.GroupsService service.
type GroupsServiceHandler interface {
	// Lists all groups for the authenticated user.
	ListGroups(context.Context, *connect.Request[v1.ListGroupsRequest]) (*connect.Response[v1.ListGroupsResponse], error)
	// Gets a specific group by ID.
	GetGroup(context.Context, *connect.Request[v1.GetGroupRequest]) (*connect.Response[v1.GetGroupResponse], error)
	// Gets multiple groups by their IDs.
	GetGroupsByIds(context.Context, *connect.Request[v1.GetGroupsByIdsRequest]) (*connect.Response[v1.GetGroupsByIdsResponse], error)
	// Creates a new group record.
	CreateGroup(context.Context, *connect.Request[v1.CreateGroupRequest]) (*connect.Response[v1.CreateGroupResponse], error)
	// Updates an existing group.
	UpdateGroup(context.Context, *connect.Request[v1.UpdateGroupRequest]) (*connect.Response[v1.UpdateGroupResponse], error)
	// Toggles the favorite status of a group.
	ToggleGroupFavorite(context.Context, *connect.Request[v1.ToggleGroupFavoriteRequest]) (*connect.Response[v1.ToggleGroupFavoriteResponse], error)
	// Syncs groups from WhatsApp instance.
	SyncGroups(context.Context, *connect.Request[v1.SyncGroupsRequest]) (*connect.Response[v1.SyncGroupsResponse], error)
	// Gets the status of a sync job.
	GetSyncStatus(context.Context, *connect.Request[v1.GetSyncStatusRequest]) (*connect.Response[v1.GetSyncStatusResponse], error)
	// Deletes a group record.
	DeleteGroup(context.Context, *connect.Request[v1.DeleteGroupRequest]) (*connect.Response[v1.DeleteGroupResponse], error)
	// Updates multiple groups at once.
	BulkUpdateGroups(context.Context, *connect.Request[v1.BulkUpdateGroupsRequest]) (*connect.Response[v1.BulkUpdateGroupsResponse], error)
	// Sends a text message to a group.
	SendGroupMessage(context.Context, *connect.Request[v1.SendGroupMessageRequest]) (*connect.Response[v1.SendGroupMessageResponse], error)
	// Sends an audio message to a group.
	SendGroupAudio(context.Context, *connect.Request[v1.SendGroupAudioRequest]) (*connect.Response[v1.SendGroupAudioResponse], error)
	// Sends an image to a group.
	SendGroupImage(context.Context, *connect.Request[v1.SendGroupImageRequest]) (*connect.Response[v1.SendGroupImageResponse], error)
	// Sends a poll to a group.
	SendGroupPoll(context.Context, *connect.Request[v1.SendGroupPollRequest]) (*connect.Response[v1.SendGroupPollResponse], error)
	// Updates the group subject/name.
	UpdateGroupSubject(context.Context, *connect.Request[v1.UpdateGroupSubjectRequest]) (*connect.Response[v1.UpdateGroupSubjectResponse], error)
	// Updates the group description.
	UpdateGroupDescription(context.Context, *connect.Request[v1.UpdateGroupDescriptionRequest]) (*connect.Response[v1.UpdateGroupDescriptionResponse], error)
	// Updates the group picture.
	UpdateGroupPicture(context.Context, *connect.Request[v1.UpdateGroupPictureRequest]) (*connect.Response[v1.UpdateGroupPictureResponse], error)
	// Updates the picture of many groups at once. Each group is routed through a
	// chip that administers it (multi-chip aware) and changes are paced per chip
	// to avoid WhatsApp anti-spam. Returns a per-group result.
	UpdateGroupPictures(context.Context, *connect.Request[v1.UpdateGroupPicturesRequest]) (*connect.Response[v1.UpdateGroupPicturesResponse], error)
	// Updates group settings (e.g., announcement mode).
	UpdateGroupSettings(context.Context, *connect.Request[v1.UpdateGroupSettingsRequest]) (*connect.Response[v1.UpdateGroupSettingsResponse], error)
	// Gets the invite code for a group.
	GetGroupInviteCode(context.Context, *connect.Request[v1.GetGroupInviteCodeRequest]) (*connect.Response[v1.GetGroupInviteCodeResponse], error)
	// Gets the participants of a group.
	GetGroupParticipants(context.Context, *connect.Request[v1.GetGroupParticipantsRequest]) (*connect.Response[v1.GetGroupParticipantsResponse], error)
	// Adds members to a group.
	AddGroupMember(context.Context, *connect.Request[v1.AddGroupMemberRequest]) (*connect.Response[v1.AddGroupMemberResponse], error)
	// Removes members from a group.
	RemoveGroupMember(context.Context, *connect.Request[v1.RemoveGroupMemberRequest]) (*connect.Response[v1.RemoveGroupMemberResponse], error)
	// Leaves a group.
	LeaveGroup(context.Context, *connect.Request[v1.LeaveGroupRequest]) (*connect.Response[v1.LeaveGroupResponse], error)
	// Promotes a member to admin.
	PromoteMember(context.Context, *connect.Request[v1.PromoteMemberRequest]) (*connect.Response[v1.PromoteMemberResponse], error)
	// Demotes a member from admin.
	DemoteMember(context.Context, *connect.Request[v1.DemoteMemberRequest]) (*connect.Response[v1.DemoteMemberResponse], error)
}

